def transform(grid):
    # Demo-validated: objects are divided by whether their bounding box encloses
    # background; enclosed objects rise, open objects fall, retaining x positions.
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            pts = []
            while stack:
                y, x = stack.pop()
                pts.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            y0, y1 = min(y for y,x in pts), max(y for y,x in pts)
            x0, x1 = min(x for y,x in pts), max(x for y,x in pts)
            zeros = {(y,x) for y in range(y0,y1+1) for x in range(x0,x1+1) if grid[y][x] == 0}
            border = [p for p in zeros if p[0] in (y0,y1) or p[1] in (x0,x1)]
            outside = set(border); todo = border[:]
            while todo:
                y,x = todo.pop()
                for p in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if p in zeros and p not in outside:
                        outside.add(p); todo.append(p)
            objects.append((bool(zeros-outside), pts, y0, y1))
    out = [[0]*w for _ in range(h)]
    for enclosed in (True, False):
        group = sorted((o for o in objects if o[0] == enclosed), key=lambda o:o[2], reverse=not enclosed)
        occupied = set()
        for _, pts, _, _ in group:
            dy = 0
            step = -1 if enclosed else 1
            while True:
                ndy = dy + step
                if any(not 0 <= y+ndy < h or (y+ndy,x) in occupied for y,x in pts):
                    break
                dy = ndy
            for y,x in pts:
                out[y+dy][x] = grid[y][x]
                occupied.add((y+dy,x))
    return out
